const $=(s,el=document)=>el.querySelector(s);
const $$=(s,el=document)=>[...el.querySelectorAll(s)];
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',table:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M9 10v10M15 10v10"/>',plan:'<path d="M4 20h16M6 16v-5M12 16V7M18 16V3"/><path d="m4 7 6-3 5 2 5-4"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M7 15h2M13 15h3"/>',building:'<rect x="5" y="3" width="14" height="18" rx="1.5"/><path d="M9 7h1M14 7h1M9 11h1M14 11h1M10 21v-5h4v5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 7v.1"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',revenue:'<path d="M3 17 9 11l4 3 8-10M15 4h6v6M3 21h18"/>',cost:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 10h18M15 15h3M7 3v4"/>',profit:'<path d="M12 2v20M17 6H9a3 3 0 0 0 0 6h6a3 3 0 0 1 0 6H6"/>',percent:'<path d="m5 19 14-14"/><circle cx="7" cy="7" r="3"/><circle cx="17" cy="17" r="3"/>',alert:'<path d="m12 3 10 17H2zM12 9v4M12 16v.1"/>',check:'<path d="m5 12 4 4L19 6"/>',link:'<path d="m9 15 6-6M8 17l-2 2a3.5 3.5 0 0 1-5-5l5-5a3.5 3.5 0 0 1 5 0M16 7l2-2a3.5 3.5 0 0 1 5 5l-5 5a3.5 3.5 0 0 1-5 0"/>',save:'<path d="M4 3h13l4 4v14H3V3zM7 3v6h10V3M7 21v-8h10v8"/>',reset:'<path d="M3 10a9 9 0 1 1 2 9M3 4v6h6"/>',trash:'<path d="M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',edit:'<path d="m14 4 6 6M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15z"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.info}</svg>`;
function icons(el=document){$$('[data-icon]',el).forEach(n=>n.innerHTML=icon(n.dataset.icon));}
const monthTH=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
const monthFull=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];
const nf=new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const valid=v=>typeof v==='number'&&Number.isFinite(v);
const money=v=>valid(v)?nf.format(v/1e6):'—';
const num=v=>valid(v)?new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(v):'—';
const pct=v=>valid(v)?v.toFixed(1)+'%':'—';
const ratio=(a,b)=>valid(a)&&valid(b)&&b!==0?a/b*100:null;
const sum=values=>values.length&&values.every(valid)?values.reduce((a,b)=>a+b,0):null;
const defaults={volume:0,price:0,raw:0,labor:0,fixed:0};
let storageOK=true;
const initialScope=D.scopes.find(s=>s.id==='pd')?.id||D.scopes[0].id;
const storageKey=id=>'pl-workspace-v2-'+window.PL_CONFIG.spreadsheetId+'-'+D.year+'-'+id;
function getSavedPlan(id){const remote=window.PL_SAVED_BY_SCOPE?.[id];if(remote?.savedAt)return remote;try{return JSON.parse(localStorage.getItem(storageKey(id))||'{}')||{};}catch(e){storageOK=false;return {};}}
let saved=getSavedPlan(initialScope);
const initialDailyDates=(D.jobOrder?.records||[]).map(record=>record.date).sort();
const state={page:'overview',scope:initialScope,period:'0',previousPeriod:'0',dailyStart:initialDailyDates[0]||'',dailyEnd:initialDailyDates.at(-1)||'',detail:false,assumptions:{...defaults},initiatives:Array.isArray(saved.initiatives)?saved.initiatives:[],savedAt:saved.savedAt||null,dirty:!!saved.draft,syncStatus:saved.savedAt?(saved.draft?'error':'saved'):'idle'};
if(saved.assumptions&&Object.values(saved.assumptions).every(valid))Object.assign(state.assumptions,saved.assumptions);
const scope=()=>D.scopes.find(s=>s.id===state.scope);
const selectedIndexes=()=>state.period==='daily'?[]:state.period==='year'?Array.from({length:12},(_,i)=>i):state.period.startsWith('q')?Array.from({length:3},(_,i)=>(Number(state.period[1])-1)*3+i):[Number(state.period)];
function aggregate(which,indexes=selectedIndexes()){
 const ps=indexes.map(i=>scope().periods[i]);
 return Object.fromEntries(D.rows.map(r=>[r.key,sum(ps.map(p=>p[which][r.key]))]));
}
function kind(){if(state.period==='daily')return 'Job-order';const kinds=[...new Set(selectedIndexes().map(i=>scope().periods[i].kind))];return kinds.length>1?'Actual + Forecast':kinds[0];}
function periodLabel(){if(state.period==='daily'){if(!state.dailyStart&&!state.dailyEnd)return 'เลือกช่วงวันที่ผลิต';const start=displayDate(state.dailyStart||state.dailyEnd),end=displayDate(state.dailyEnd||state.dailyStart);return start===end?start:`${start}–${end}`;}return state.period==='year'?'มกราคม–ธันวาคม '+D.year:state.period.startsWith('q')?'ไตรมาส '+state.period[1]+' / '+D.year:monthFull[Number(state.period)]+' '+D.year;}
function displayDate(value){const match=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return match?`${match[3]}/${match[2]}/${match[1]}`:String(value||'');}
function dailyRecords(){const start=state.dailyStart||state.dailyEnd,end=state.dailyEnd||state.dailyStart;return (D.jobOrder?.records||[]).filter(record=>record.date>=start&&record.date<=end);}
function normalizedModel(value){return String(value||'').trim().replace(/-S$/i,'').toUpperCase();}
function prefixMatchPercent(left,right){const a=normalizedModel(left),b=normalizedModel(right);if(!a||!b)return 0;let prefix=0;while(prefix<Math.min(a.length,b.length)&&a[prefix]===b[prefix])prefix++;return prefix/Math.max(a.length,b.length)*100;}
function priceMatchForModel(model){const key=normalizedModel(model);if(!key)return null;const unique=new Map();for(const item of D.products||[]){if(!valid(item.fcTHB))continue;const sourceModel=item.forecastModel||item.model,candidate=normalizedModel(sourceModel);if(!candidate)continue;const score=prefixMatchPercent(key,candidate),id=`${candidate}|${item.fcTHB}|${item.fcTHBSource||''}`;if(!unique.has(id))unique.set(id,{sourceModel,price:item.fcTHB,priceSource:item.fcTHBSource||'Sale Price',exchangeRate:item.fcExchangeRate,score});}const candidates=[...unique.values()],exact=candidates.filter(match=>match.score===100),eligible=exact.length?exact:candidates.filter(match=>match.score>=95);if(!eligible.length)return null;eligible.sort((a,b)=>b.score-a.score||a.sourceModel.length-b.sourceModel.length);const score=eligible[0].score,top=eligible.filter(match=>match.score===score),prices=new Set(top.map(match=>match.price));if(prices.size>1)return {ambiguous:true,score,candidates:top};return {...top[0],score,exact:score===100};}
function dailySummary(){
 const records=dailyRecords(),groups=new Map(),hours=Array(24).fill(0);let qty=0,pricedQty=0,estimatedValue=0;const jobs=new Set();
 for(const record of records){
  qty+=record.qty;jobs.add(record.jobNo);const hour=Number(record.time?.slice(0,2));if(Number.isInteger(hour)&&hour>=0&&hour<24)hours[hour]+=record.qty;
  const key=normalizedModel(record.model),match=priceMatchForModel(record.model),group=groups.get(key)||{model:record.model,qty:0,jobs:new Set(),priceMatch:match,price:match&&!match.ambiguous?match.price:null,value:0};
  group.qty+=record.qty;group.jobs.add(record.jobNo);if(valid(group.price))group.value+=record.qty*group.price;groups.set(key,group);
 }
 const models=[...groups.values()].map(group=>{if(valid(group.price)){pricedQty+=group.qty;estimatedValue+=group.value;}return {...group,jobCount:group.jobs.size};}).sort((a,b)=>b.qty-a.qty);
 return {records,qty,jobs:jobs.size,models,hours,estimatedValue,pricedQty,modelCount:models.length};
}
function dailyKpi(label,value,unit,ico,detail,featured=false){return `<div class="kpi ${featured?'featured':''}"><div class="kpi-label">${label}<span data-icon="${ico}"></span></div><div class="kpi-value">${value}<small>${unit}</small></div><div class="kpi-bottom">${detail}</div></div>`;}
function dailyHourlyChart(hours){const W=700,H=228,L=42,R=9,T=10,Y=181,B=29,slot=(W-L-R)/24,max=Math.max(1,...hours);let svg='';for(let i=0;i<=3;i++){const y=Y-i*Y/3;svg+=`<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="#edf1f4"/><text x="${L-8}" y="${y+3}" text-anchor="end">${Math.round(max*i/3)}</text>`;}hours.forEach((qty,hour)=>{const height=qty/max*(Y-T);const x=L+hour*slot+2;if(qty)svg+=`<rect x="${x}" y="${Y-height}" width="${Math.max(2,slot-4)}" height="${height}" rx="2" fill="#44998c"><title>${String(hour).padStart(2,'0')}:00 · ${num(qty)} ชิ้น</title></rect>`;if(hour%2===0)svg+=`<text x="${L+(hour+.5)*slot}" y="${Y+B-3}" text-anchor="middle">${String(hour).padStart(2,'0')}</text>`;});return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="จำนวนผลิตตามชั่วโมง ช่วง ${periodLabel()}">${svg}</svg>`;}
function dailyDashboard(){
 const source=D.jobOrder,summary=dailySummary();
 if(source?.status!=='loaded')return `<section class="panel daily-empty"><div class="daily-empty-icon" data-icon="alert"></div><h2>ยังอ่านข้อมูล Job-order Tracking ไม่ได้</h2><p>${escapeHTML(source?.error||'ตรวจ URL ของ CSV ที่เผยแพร่จากชีตยอดผลิตใน site/pl-settings.js')}</p><a class="button secondary small" href="https://github.com/jrh91234/Job-order-tracking" target="_blank" rel="noreferrer">เปิด Repo Job-order Tracking ↗</a></section>`;
 if(state.scope!=='pd')return `<div class="context-notice"><span data-icon="info"></span>ข้อมูลรายวันจาก Job-order Tracking ชุดนี้เป็นข้อมูลการผลิตของแผนก PD กรุณาเลือก “แผนก PD” เพื่อดูข้อมูล</div>`;
 if(!summary.records.length)return `<section class="panel daily-empty"><div class="daily-empty-icon" data-icon="calendar"></div><h2>ไม่มีรายการผลิตในช่วงวันที่ ${escapeHTML(periodLabel())}</h2><p>ข้อมูลใน Job-order Tracking ครอบคลุม ${escapeHTML(displayDate(source.firstDate))} ถึง ${escapeHTML(displayDate(source.lastDate))}</p></section>`;
 const latestPrice=summary.pricedQty?nf.format(summary.estimatedValue)+' บาท':'ไม่มีราคา FC ที่จับคู่กับรุ่นสินค้า';
 const modelRows=summary.models.map(group=>{const match=group.priceMatch,matchNote=!match?'ไม่พบรุ่นใน Sale Price ที่ตรงตั้งแต่ 95%':match.ambiguous?`คะแนน ${match.score.toFixed(1)}% มีหลายฐานราคา: ${match.candidates.map(item=>escapeHTML(item.sourceModel)).join(', ')}`:`ฐานราคา: ${escapeHTML(match.sourceModel)} · ${match.exact?'ตรงรุ่นหลังตัด -S · 100%':`อักษรนำตรง ${match.score.toFixed(1)}%`} · ${escapeHTML(match.priceSource)}${match.priceSource.includes('Rate')?` ${num(match.exchangeRate)}`:''}`;return `<tr><td>${escapeHTML(group.model)}<div class="row-description">${group.jobCount} Job orders</div><div class="row-description price-match-note">${matchNote}</div></td><td>${num(group.qty)}</td><td>${valid(group.price)?nf.format(group.price):'—'}</td><td>${valid(group.price)?nf.format(group.value):'—'}</td></tr>`;}).join('');
 const sortedRecords=summary.records.slice().sort((a,b)=>b.ts-a.ts),shownRecords=sortedRecords.slice(0,500);
 const logRows=shownRecords.map(record=>`<tr><td>${escapeHTML(displayDate(record.date))}</td><td>${escapeHTML(record.time)}</td><td>${escapeHTML(record.jobNo)}</td><td>${escapeHTML(record.model)}</td><td>${num(record.qty)}</td><td>${escapeHTML(record.line)}</td><td>${escapeHTML(record.shift)}</td></tr>`).join('');
 const logCount=sortedRecords.length>shownRecords.length?`แสดง ${num(shownRecords.length)} รายการล่าสุด จากทั้งหมด ${num(sortedRecords.length)} รายการ · ส่งออก CSV เพื่อดูทั้งหมด`:`${num(sortedRecords.length)} รายการ · แสดงเวลาล่าสุดก่อน`;
 return `<div class="daily-source-note"><span class="status">Job-order Tracking</span><span>ข้อมูลผลิตล่าสุดในชีต ${escapeHTML(displayDate(source.lastDate))} · อ่านข้อมูล ${num(source.records.length)} รายการ</span></div><div class="daily-kpi-grid">${dailyKpi('จำนวนผลิต FG',num(summary.qty),'ชิ้น','revenue','รวมข้อมูลที่ไม่เป็น VOID และตัดรายการซ้ำ')}${dailyKpi('Job orders',num(summary.jobs),'งาน','table',`${summary.modelCount} รุ่นสินค้า`)}${dailyKpi('รุ่นที่ผลิต',num(summary.modelCount),'รุ่น','building',`ช่วง ${escapeHTML(periodLabel())}`)}${dailyKpi('มูลค่าผลิตโดยประมาณ',latestPrice,'','profit',`ราคา FC ต่อหน่วย · ครอบคลุม ${num(summary.pricedQty)} จาก ${num(summary.qty)} ชิ้น`,true)}</div><div class="daily-notice"><span data-icon="info"></span><span>จำนวนผลิตจาก FG Qty ใน CSV · ราคาอ้างอิง Sale Price: จับคู่ exact หลังตัด -S ท้าย หรือเทียบอักษรนำตั้งแต่ 95% และแสดงรุ่นฐานใต้ชื่อรุ่น · ถ้าราคา FC BHT ว่าง จะคำนวณจาก FC USD × Rate ในชีต · มูลค่านี้เป็นค่าประมาณ ไม่ใช่ยอดขายหรือกำไร และไม่รวมใน P&amp;L รายเดือน</span></div><div class="daily-content-grid"><section class="panel"><div class="panel-head"><div><h2>ปริมาณผลิตตามชั่วโมงในช่วง</h2><p>${escapeHTML(periodLabel())} · รวมทุกวันที่เลือก · หน่วย: ชิ้น</p></div></div><div class="chart daily-chart">${dailyHourlyChart(summary.hours)}</div></section><section class="panel"><div class="panel-head"><div><h2>ผลผลิตตามรุ่น</h2><p>มูลค่าคำนวณจากราคา FC ต่อหน่วย</p></div></div><div class="table-wrap daily-model-table"><table><thead><tr><th>รุ่นสินค้า / Job orders</th><th>จำนวนผลิต (ชิ้น)</th><th>ราคา FC (บาท/หน่วย)</th><th>มูลค่าประมาณการ (บาท)</th></tr></thead><tbody>${modelRows}</tbody></table></div></section></div><section class="panel daily-log-panel"><div class="panel-head"><div><h2>รายการผลิตรายชั่วโมง</h2><p>${logCount}</p></div></div><div class="table-wrap"><table><thead><tr><th>วันที่</th><th>เวลา</th><th>Job order</th><th>รุ่นสินค้า</th><th>จำนวน FG (ชิ้น)</th><th>Line</th><th>กะ</th></tr></thead><tbody>${logRows}</tbody></table></div></section>`;
}
function diff(result,bp){return valid(result)&&valid(bp)?result-bp:null;}
function varianceHTML(result,bp,expense=false){const v=diff(result,bp);return valid(v)?`<span class="variance ${(expense?-v:v)>=0?'positive':'negative'}">${v>0?'+':''}${money(v)}</span>`:'<span class="muted">—</span>';}
function changeBadge(result,bp,expense=false){const p=ratio(diff(result,bp),Math.abs(bp));return valid(p)?`<span class="change ${(expense?-p:p)<0?'bad':''}">${p>=0?'↗':'↘'} ${Math.abs(p).toFixed(1)}%</span>`:'<span class="change">ไม่มี BP</span>';}
function kpi(label,value,ico,result,bp,expense=false,featured=false,percentage=false){return `<div class="kpi ${featured?'featured':''}"><div class="kpi-label">${label}<span data-icon="${ico}"></span></div><div class="kpi-value">${percentage?pct(value):money(value)}${percentage?'':'<small>ลบ.</small>'}</div><div class="kpi-bottom">${changeBadge(result,bp,expense)}<span>${state.page==='plan'?'เทียบ Forecast เดิม':'เทียบ Business Plan'}</span></div></div>`;}
function KPIHTML(){const a=aggregate('result'),b=aggregate('bp');const cost=valid(a.vc)&&valid(a.fc)?a.vc+a.fc:null,bCost=valid(b.vc)&&valid(b.fc)?b.vc+b.fc:null;return `<div class="kpi-grid">${kpi('รายได้รวม',a.revenue,'revenue',a.revenue,b.revenue)}${kpi('ต้นทุนผันแปร + คงที่',cost,'cost',cost,bCost,true)}${kpi('กำไรสุทธิ',a.net,'profit',a.net,b.net,false,true)}${kpi('อัตรากำไรสุทธิ',ratio(a.net,a.revenue),'percent',ratio(a.net,a.revenue),ratio(b.net,b.revenue),false,false,true)}</div>`;}
function revenueChart(){
 const ps=scope().periods,max=Math.max(1,...ps.flatMap(p=>[p.bp.revenue,p.result.revenue]).filter(valid));const top=Math.ceil(max/1e6/50)*50;const W=660,H=235,left=43,right=13,bottom=29,Y=190,cw=(W-left-right)/12;
 const selected=new Set(selectedIndexes());let svg='';
 for(let j=0;j<=4;j++){const y=Y-j*Y/4;svg+=`<line x1="${left}" y1="${y}" x2="${W-right}" y2="${y}" stroke="#edf1f4"/><text x="${left-10}" y="${y+4}" text-anchor="end">${Math.round(top*j/4)}</text>`;}
 ps.forEach((p,i)=>{const x=left+i*cw;if(selected.has(i))svg+=`<rect class="actual-band" x="${x+1}" y="0" width="${cw-2}" height="${Y}" rx="4"/>`;[p.bp.revenue,p.result.revenue].forEach((v,j)=>{if(!valid(v)){svg+=`<text x="${x+12+j*16}" y="${Y-7}" text-anchor="middle">—</text>`;return;}const h=v/1e6/top*Y;svg+=`<rect class="chart-bar" data-month="${i}" x="${x+8+j*15}" y="${Y-h}" width="11" height="${Math.max(h,.5)}" rx="2" fill="${j?'#44998c':'#dce5eb'}"><title>${monthFull[i]} · ${j?p.kind:'BP'}: ${money(v)} ล้านบาท</title></rect>`;});svg+=`<text class="month-label" x="${x+cw/2}" y="${Y+21}" text-anchor="middle">${p.month}</text>`;});
 return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="กราฟรายได้ BP เทียบ Actual / Forecast ปี ${D.year}">${svg}</svg>`;
}
function donut(){const a=aggregate('result');const labor=sum([a.labor,a.ot,a.sc??0,a.scot??0]);const total=sum([a.vc,a.fc]);const other=valid(a.vc)&&valid(a.rm)&&valid(labor)?a.vc-a.rm-labor:null;const groups=[['วัตถุดิบ',a.rm,'#3d9686'],['ค่าแรงและ OT',labor,'#72b5a4'],['ต้นทุนผันแปรอื่น',other,'#c3d9ce'],['ต้นทุนคงที่',a.fc,'#b3c1d0']];let offset=0;let seg='';if(valid(total)&&total>0&&groups.every(g=>valid(g[1])&&g[1]>=0)){groups.forEach(([label,v,col])=>{const f=v/total*100;seg+=`<circle cx="80" cy="80" r="64" fill="none" stroke="${col}" stroke-width="15" pathLength="100" stroke-dasharray="${Math.max(0,f-.8)} ${100-Math.max(0,f-.8)}" stroke-dashoffset="${-offset}"><title>${label}: ${money(v)} ล้านบาท (${pct(f)})</title></circle>`;offset+=f;});}return `<div class="donut-wrap"><svg viewBox="0 0 160 160" role="img" aria-label="สัดส่วนต้นทุน"><circle cx="80" cy="80" r="64" fill="none" stroke="#f0f4f6" stroke-width="15"/>${seg}</svg><div class="donut-center">ต้นทุนรวม<strong>${money(total)}</strong>ล้านบาท</div></div><div class="cost-legend">${groups.map(([l,v,c])=>`<div class="cost-item"><i style="background:${c}"></i>${l}<strong>${money(v)}</strong><em>${pct(ratio(v,total))}</em></div>`).join('')}</div>`;}
const summaryKeys=['revenue','vc','cm','fc','profit','net'];
function tableRows(full=false){const a=aggregate('result'),b=aggregate('bp');return D.rows.filter(r=>full||summaryKeys.includes(r.key)).map(r=>`<tr class="row-${r.type}"><td><div class="row-label">${r.label}${full?`<button class="row-ref" data-reference="${r.key}" aria-label="ดูแหล่งข้อมูล ${r.label}">${icon('link')}</button>`:''}</div>${full?`<div class="row-description">${r.en}</div>`:''}</td><td>${money(b[r.key])}</td><td class="${valid(a[r.key])&&a[r.key]<0?'negative':''}">${money(a[r.key])}</td><td>${varianceHTML(a[r.key],b[r.key],r.type==='expense'||r.type==='subtotal')}</td>${full?`<td>${pct(ratio(diff(a[r.key],b[r.key]),Math.abs(b[r.key])))}</td><td>${pct(ratio(a[r.key],a.revenue))}</td>`:''}</tr>`).join('');}
function insights(){const a=aggregate('result'),b=aggregate('bp');const revP=ratio(diff(a.revenue,b.revenue),Math.abs(b.revenue));const rmP=ratio(a.rm,a.revenue),rmBP=ratio(b.rm,b.revenue);const netD=diff(a.net,b.net);return `<div class="insights"><div class="insight"><span class="insight-icon ${revP<0?'amber':''}" data-icon="revenue"></span><div><h3>${valid(revP)?'รายได้'+(revP<0?'ต่ำ':'สูง')+'กว่าแผน '+Math.abs(revP).toFixed(1)+'%':'ยังเปรียบเทียบรายได้กับ BP ไม่ได้'}</h3><p>${valid(b.revenue)?`รายได้ ${money(a.revenue)} ลบ. จากเป้าหมาย <strong>${money(b.revenue)} ลบ.</strong>`:'สูตรรายได้ BP ในต้นทางอ่านค่าไม่ได้ ตรวจสอบที่หน้าข้อมูลต้นทาง'}</p></div></div><div class="insight"><span class="insight-icon" data-icon="cost"></span><div><h3>วัตถุดิบคิดเป็น ${pct(rmP)} ของรายได้</h3><p>${valid(rmBP)?`แผน ${pct(rmBP)} · ต่างกัน <strong>${Math.abs(rmP-rmBP).toFixed(1)} จุดเปอร์เซ็นต์</strong>`:'ข้อมูล BP ของวัตถุดิบยังไม่พร้อมเปรียบเทียบ'}</p></div></div><div class="insight"><span class="insight-icon ${netD<0?'amber':''}" data-icon="profit"></span><div><h3>${valid(netD)?`กำไรสุทธิ${netD<0?'ต่ำ':'สูง'}กว่าแผน ${money(Math.abs(netD))} ลบ.`:'ตรวจสอบข้อมูลกำไรสุทธิก่อนวางแผน'}</h3><p>ปรับสมมติฐานยอดขายและต้นทุนใน Business Plan เพื่อดูผลกระทบต่อกำไรทั้งปี</p></div></div></div>`;}
function sourceNotice(){const a=aggregate('result'),b=aggregate('bp');if(!valid(a.revenue)||!valid(a.net)||!valid(b.revenue)||!valid(b.net))return `<div class="context-notice"><span data-icon="alert"></span>บางค่ามีสูตรผิดพลาดในต้นทาง แสดง “—” และไม่นำมาแทนด้วยศูนย์<button data-action="sources">ดูข้อมูลต้นทาง ↗</button></div>`;return '';}
function overview(){if(state.period==='daily')return dailyDashboard();return `${sourceNotice()}${KPIHTML()}<div class="chart-grid"><section class="panel"><div class="panel-head"><div><h2>รายได้เทียบ Business Plan</h2><p>รายเดือน · ปี ${D.year} · ล้านบาท</p></div><div class="legend"><span><i class="gray"></i>Business Plan</span><span><i class="teal"></i>Actual / Forecast</span></div></div><div class="chart">${revenueChart()}</div><div class="chart-foot"><span>Actual / Forecast ตามหัวตาราง Google Sheets</span><strong>คลิกแท่งกราฟเพื่อเลือกเดือน</strong></div></section><section class="panel cost-panel"><div class="panel-head"><div><h2>โครงสร้างต้นทุน</h2><p>${periodLabel()} · ${scope().label}</p></div><span data-icon="cost" class="muted"></span></div>${donut()}</section></div><div class="lower-grid"><section class="panel"><div class="panel-head"><div><h2>สรุป Profit & Loss</h2><p>${kind()} เทียบแผนในช่วงเวลาเดียวกัน</p></div><a class="link" href="#pnl">ดูรายละเอียด ${icon('arrow')}</a></div><div class="table-wrap summary-table"><table><thead><tr><th>รายการ</th><th>BP</th><th>${kind()}</th><th>ผลต่าง</th></tr></thead><tbody>${tableRows()}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>ประเด็นที่ควรติดตาม</h2><p>คำนวณจากข้อมูลในช่วงเวลาที่เลือก</p></div><span data-icon="spark" class="muted"></span></div>${insights()}</section></div>`;}
function pnl(){if(state.period==='daily')return dailyDashboard();return `${sourceNotice()}${KPIHTML()}<section class="panel"><div class="toolbar"><div class="segmented"><button data-detail="false" class="${!state.detail?'active':''}">สรุป P&L</button><button data-detail="true" class="${state.detail?'active':''}">รายละเอียดต้นทุน</button></div><span class="table-subtitle">${scope().label} · ${periodLabel()} · ล้านบาท</span></div><div class="table-wrap"><table class="pnl-table"><thead><tr><th>รายการ / Account group</th><th>Business Plan</th><th>${kind()}</th><th>ผลต่าง (ลบ.)</th><th>ผลต่าง (%)</th><th>% ต่อรายได้</th></tr></thead><tbody>${(()=>{const t=tableRows(state.detail);if(state.detail)return t;const a=aggregate('result'),b=aggregate('bp');return D.rows.filter(r=>summaryKeys.includes(r.key)||['other','extra','interest','tax'].includes(r.key)).map(r=>`<tr class="row-${r.type}"><td>${r.label}<div class="row-description">${r.en}</div></td><td>${money(b[r.key])}</td><td>${money(a[r.key])}</td><td>${varianceHTML(a[r.key],b[r.key],r.type==='expense'||r.type==='subtotal')}</td><td>${pct(ratio(diff(a[r.key],b[r.key]),Math.abs(b[r.key])))}</td><td>${pct(ratio(a[r.key],a.revenue))}</td></tr>`).join('');})()}</tbody></table></div><div class="table-note">ผลต่าง = Actual / Forecast − BP · สีเขียวหมายถึงรายได้หรือกำไรสูงกว่าแผน หรือต้นทุนต่ำกว่าแผน<br>กำไรจากการดำเนินงาน = รายได้ − ต้นทุนผันแปร − ต้นทุนคงที่ · กำไรสุทธิรวมรายได้อื่น หักค่าใช้จ่ายพิเศษ ดอกเบี้ย และภาษีตามเอกสาร<br>“—” หมายถึงค่าว่างหรือค่าที่อ่านไม่ได้ · ตัวเลขรวมใช้ผลรวมรายเดือน และอ่านค่าที่ Google Sheets คำนวณไว้ในขณะเชื่อมต่อ</div></section>`;}
const drivers=[['volume','ปริมาณขาย',-30,50,'วัตถุดิบ, OT และ OH ผันแปรตามปริมาณขาย'],['price','ราคาขายต่อหน่วย',-20,30,'ปรับรายได้ · ค่าใช้จ่ายขายปรับตามรายได้'],['raw','ราคาวัตถุดิบต่อหน่วย',-20,30,'ปรับต้นทุน RM หลังปรับปริมาณขาย'],['labor','ค่าแรงทางตรง',-30,40,'ค่าแรงทางตรงและจ้างเหมาปรับด้วยอัตรานี้'],['fixed','ลดต้นทุนคงที่',-20,30,'ค่าบวกหมายถึงต้นทุนคงที่ลดลง']];
function model(){const s=scope();const m=state.assumptions;return s.periods.map((p,i)=>{const a=p.result;if(p.kind==='Actual')return {...a,month:p.month,kind:'Actual'};if(!['revenue','rm','labor','ot','sc','scot','ohvc','selling','vc','fc','profit','net'].every(k=>valid(a[k])))return {month:p.month,kind:'Scenario',unavailable:true,revenue:null,net:null,profit:null};const vol=1+m.volume/100,price=1+m.price/100,raw=1+m.raw/100,labor=1+m.labor/100;const r={...a,month:p.month,kind:'Scenario'};r.revenue=a.revenue*vol*price;r.rm=a.rm*vol*raw;r.labor=a.labor*labor;r.sc=a.sc*labor;r.ot=a.ot*vol;r.scot=a.scot*vol;r.ohvc=a.ohvc*vol;r.selling=a.selling*vol*price;r.vc=a.vc+(r.rm-a.rm)+(r.labor-a.labor)+(r.sc-a.sc)+(r.ot-a.ot)+(r.scot-a.scot)+(r.ohvc-a.ohvc)+(r.selling-a.selling);r.cm=r.revenue-r.vc;r.fc=a.fc*(1-m.fixed/100);r.profit=r.cm-r.fc;r.net=a.net+(r.profit-a.profit);return r;});}
function projectionSVG(ms){const base=scope().periods.map(p=>p.result.net);const values=[...base,...ms.map(p=>p.net)].filter(valid);const min=Math.min(0,...values)/1e6,max=Math.max(1,...values)/1e6;const range=max-min||1;const W=650,H=185,L=34,R=16,T=15,B=30,w=W-L-R,h=H-T-B;const x=i=>L+i*w/11,y=v=>T+(max-v/1e6)/range*h;let out='';for(let j=0;j<4;j++){let val=min+range*j/3,yy=y(val*1e6);out+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#eef1f4"/><text x="${L-8}" y="${yy+3}" text-anchor="end" font-size="9" fill="#a1adba">${val.toFixed(0)}</text>`;}function line(arr,col,dashed){let segments=[],curr=[];arr.forEach((v,i)=>{if(valid(v))curr.push([x(i),y(v)]);else if(curr.length){segments.push(curr);curr=[];}});if(curr.length)segments.push(curr);segments.forEach(seg=>{const d=seg.map(([xx,yy],i)=>(i?'L':'M')+xx+','+yy).join(' ');out+=`<path d="${d}" stroke="${col}" stroke-width="2" fill="none" ${dashed?'stroke-dasharray="4 4"':''}/>`;});arr.forEach((v,i)=>{if(valid(v))out+=`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${col}"><title>${monthFull[i]}: ${money(v)} ล้านบาท</title></circle>`;});}line(base,'#b9c7d4',true);line(ms.map(p=>p.net),'#328d7d',false);scope().periods.forEach((p,i)=>out+=`<text x="${x(i)}" y="${H-8}" text-anchor="middle" font-size="9" fill="#92a0ae">${p.month}</text>`);return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="กำไรสุทธิรายเดือนของแผนจำลองเทียบ Forecast เดิม">${out}</svg>`;}
function planResults(){const ms=model(),annual=sum(ms.map(p=>p.net)),revenue=sum(ms.map(p=>p.revenue)),base=sum(scope().periods.map(p=>p.result.net));return `<div class="kpi-grid">${kpi('รายได้ทั้งปี',revenue,'revenue',revenue,sum(scope().periods.map(p=>p.result.revenue)))}${kpi('กำไรสุทธิทั้งปี',annual,'profit',annual,base,false,true)}<div class="kpi"><div class="kpi-label">ผลต่อกำไรสุทธิ<span data-icon="spark"></span></div><div class="kpi-value ${diff(annual,base)<0?'negative':'positive'}">${valid(diff(annual,base))&&diff(annual,base)>0?'+':''}${money(diff(annual,base))}<small>ลบ.</small></div><div class="kpi-bottom">เทียบ Forecast เดิม · คงเดือน Actual</div></div></div><section class="panel"><div class="panel-head"><div><h2>แผนใหม่ส่งผลต่อกำไรอย่างไร</h2><p>กำไรสุทธิรายเดือน · ล้านบาท</p></div><div class="legend"><span><i class="gray"></i>เดิม</span><span><i class="teal"></i>แผนจำลอง</span></div></div><div class="projection-chart">${projectionSVG(ms)}</div><div class="plan-note">จำลองเฉพาะเดือน Forecast · คงค่าเดือน Actual ตามหัวตาราง · รายได้อื่น ค่าใช้จ่ายพิเศษ ดอกเบี้ย และภาษีคงตามค่าต้นทาง</div></section><section class="panel plan-months"><div class="panel-head"><h2>ประมาณการรายเดือน</h2><span class="table-subtitle">ล้านบาท</span></div><div class="table-wrap"><table><thead><tr><th>เดือน</th><th>รายได้ใหม่</th><th>กำไรเดิม</th><th>กำไรใหม่</th><th>ผลต่อกำไร</th></tr></thead><tbody>${ms.map((p,i)=>`<tr><td>${monthTH[i]} ${p.kind==='Actual'?'<span class="status">Actual</span>':''}</td><td>${money(p.revenue)}</td><td>${money(scope().periods[i].result.net)}</td><td class="${p.net<0?'negative':'positive'}">${money(p.net)}</td><td>${varianceHTML(p.net,scope().periods[i].result.net)}</td></tr>`).join('')}<tr class="row-final"><td>รวมทั้งปี</td><td>${money(revenue)}</td><td>${money(base)}</td><td>${money(annual)}</td><td>${varianceHTML(annual,base)}</td></tr></tbody></table></div></section>`;}
function initiativesHTML(){return `<section class="panel initiatives"><div class="panel-head"><div><h2>แผนงานของแผนก</h2><p>ผูกแผนธุรกิจกับผู้รับผิดชอบและเป้าหมาย · ยังไม่รวมผลประหยัดในแบบจำลอง</p></div><button class="button secondary small" data-action="add-initiative">${icon('plus')}เพิ่มแผนงาน</button></div><div class="initiative-list">${state.initiatives.length?state.initiatives.map((a,i)=>`<div class="initiative"><span class="initiative-code">${String(i+1).padStart(2,'0')}</span><div><h3>${escapeHTML(a.title)}</h3><p>${escapeHTML(a.owner)} · เป้าหมาย ${escapeHTML(a.goal||'ยังไม่ระบุ')} · กำหนด ${escapeHTML(a.due||'ยังไม่ระบุ')}</p></div><span class="status initiative-status ${a.status==='เสร็จแล้ว'?'':a.status==='กำลังดำเนินการ'?'forecast':'warning'}">${escapeHTML(a.status)}</span><div class="initiative-controls"><button class="icon-button" data-edit-initiative="${i}" aria-label="แก้ไขแผนงาน">${icon('edit')}</button><button class="icon-button" data-delete-initiative="${i}" aria-label="ลบแผนงาน">${icon('trash')}</button></div></div>`).join(''):'<div class="empty-state"><strong>เพิ่มแผนงานที่ช่วยให้แผนกถึงเป้าหมาย</strong>เช่น ลดการสูญเสียวัตถุดิบ ปรับ OT หรือเพิ่มยอดขาย</div>'}</div></section>`;}
function plan(){const bad=model().some(p=>p.unavailable);return `<div class="plan-intro"><div><h2>Business Plan ${D.year} · ${scope().label}</h2><p>ปรับสมมติฐานของเดือน Forecast และดูผลกระทบทั้งปี โดยคงเดือน Actual</p></div><span class="status">แผนจำลอง</span></div>${bad?'<div class="context-notice"><span data-icon="alert"></span>ข้อมูล Forecast ของหน่วยงานนี้มีค่าว่างหรือสูตรผิดพลาด จึงยังคำนวณแผนครบทั้งปีไม่ได้ กรุณาตรวจชีตต้นทาง</div>':''}<div class="plan-layout"><section class="panel assumptions"><div class="panel-head"><div><h2>สมมติฐานของแผน</h2><p>เปลี่ยนแปลงจาก Forecast ใน Google Sheets (%)</p></div><span data-icon="plan" class="muted"></span></div><div class="assumption-fields">${drivers.map(([key,l,min,max,desc])=>`<div class="assumption"><div class="field-top"><label for="driver-${key}">${l}</label><div class="number-input"><input id="driver-${key}" data-driver="${key}" type="number" min="${min}" max="${max}" step="0.5" value="${state.assumptions[key]}" aria-label="${l} เปอร์เซ็นต์"><span>%</span></div></div><input type="range" data-slider="${key}" min="${min}" max="${max}" step="0.5" value="${state.assumptions[key]}" aria-label="ปรับ ${l}"><p>${desc}</p></div>`).join('')}</div><div class="assumptions-footer"><button class="button primary small" data-action="save-plan">${icon('save')}บันทึกแผน</button><button class="button secondary small" data-action="reset-plan">${icon('reset')}คืนค่าฐาน</button></div><div class="save-state" style="padding:12px 20px 0" id="save-state">${saveLabel()}</div></section><div class="plan-results" id="plan-results">${planResults()}</div></div>${initiativesHTML()}`;}
function saveLabel(){return state.syncStatus==='saving'?'กำลังบันทึกใน Google Sheets…':state.syncStatus==='error'?'บันทึกลง Google Sheets ไม่สำเร็จ':state.dirty?'มีการเปลี่ยนแปลงที่ยังไม่ได้บันทึก':state.savedAt?'บันทึกใน Google Sheets '+new Date(state.savedAt).toLocaleString('th-TH',{timeZone:'Asia/Bangkok',dateStyle:'short',timeStyle:'short'}):'ยังไม่ได้บันทึกใน Google Sheets';}
function sourceErrorsHTML(){const errors=D.errors.slice(0,8);if(!errors.length)return '';return `<section class="panel"><div class="panel-head"><div><h2>ตัวอย่างสูตรที่อ่านไม่ได้</h2><p>แสดง ${errors.length} จาก ${num(D.errors.length)} เซลล์ ในช่วงที่เว็บอ่าน</p></div></div><div class="table-wrap"><table><thead><tr><th>ชีต</th><th>เซลล์</th><th>ข้อผิดพลาด</th></tr></thead><tbody>${errors.map(e=>`<tr><td>${escapeHTML(e.sheet)}</td><td>${escapeHTML(e.cell)}</td><td>${escapeHTML(e.error)}<div class="row-description">${escapeHTML(e.message||'ตรวจสูตรในชีตต้นทาง')}</div></td></tr>`).join('')}</tbody></table></div></section>`;}
function sources(){return `<div class="source-grid"><section class="panel source-card"><div class="eyebrow">GOOGLE SHEETS</div><div class="source-file"><div class="file-mark">GS</div><div><h3>${escapeHTML(D.source)}</h3><p>ข้อมูลที่อ่านล่าสุด · หน่วยเงิน THB · ปี P&L ${D.year}</p></div></div><div class="source-stats"><div><strong>${D.sources.length}</strong><span>แท็บในชีต</span></div><div><strong>${D.scopes.length}</strong><span>ขอบเขต P&L</span></div><div><strong>${D.products.length}</strong><span>รายการราคาที่อ่านได้</span></div></div></section><section class="panel"><div class="panel-head"><div><h2>ขอบเขตของข้อมูล</h2><p>ใช้ประกอบการอ่านผลและวางแผน</p></div><span data-icon="info" class="muted"></span></div><div class="info-list"><div>${icon('check')}<span>แยก BP, Actual และ Forecast ตามหัวตาราง และรวมเฉพาะเดือนเพื่อไม่ให้นับไตรมาสซ้ำ</span></div><div>${icon('check')}<span>แผนก PD และบริษัทเป็นคนละขอบเขต ห้ามรวมยอดเข้าด้วยกัน</span></div><div>${icon('alert')}<span>ค่าว่างและสูตรผิดพลาดแสดงเป็น “—” หากฐาน Forecast ไม่ครบ จะไม่แสดงยอดแผนทั้งปี</span></div><div>${icon('info')}<span>บันทึกประวัติแผนใน business_plans เมื่อกดบันทึกครั้งแรกจะสร้างแท็บนี้ ผู้บันทึกต้องมีสิทธิ์ Editor</span></div></div></section></div><section class="panel"><div class="panel-head"><div><h2>แหล่งข้อมูลต้นทาง</h2><p>แท็บ P&L และข้อมูลรายวันจาก Job-order Tracking</p></div><input class="search" id="source-search" placeholder="ค้นหาชื่อชีต..." aria-label="ค้นหาชื่อชีต"></div><div class="table-wrap source-table"><table><thead><tr><th>แท็บต้นทาง</th><th>บทบาทในระบบ</th><th>ขอบเขต / ช่วงตรวจ</th><th>ข้อผิดพลาดที่พบ</th></tr></thead><tbody id="source-rows">${sourceRows('')}</tbody></table></div><div class="table-note">จำนวนข้อผิดพลาดรวมคอลัมน์เปอร์เซ็นต์และตารางประกอบในช่วงที่ระบุ ไม่ใช่จำนวนรายการ P&L<br>ปี P&L ใช้ปีจากหัวตารางหลัก ควรตรวจปีของรายละเอียดสินค้าและการลงทุนก่อนใช้ประกอบแผน</div></section>${sourceErrorsHTML()}<section class="panel sources-bottom"><div class="panel-head"><div><h2>ราคาขายและวัตถุดิบตามรุ่นสินค้า</h2><p>Sale Price · BP ${valid(D.exchangeBP)?nf.format(D.exchangeBP):'—'} บาท/USD · FC ${valid(D.exchangeFC)?nf.format(D.exchangeFC):'—'} บาท/USD</p></div></div><div class="table-wrap"><table><thead><tr><th>รุ่นสินค้า BP / FC</th><th>BP Process USD</th><th>BP RM USD</th><th>BP บาท/หน่วย</th><th>FC Price USD</th><th>FC RM USD</th><th>FC บาท/หน่วย</th><th>FC RM / Price</th></tr></thead><tbody>${D.products.map(p=>`<tr><td>${escapeHTML(p.model)}${p.forecastModel?`<div class="row-description">FC: ${escapeHTML(p.forecastModel)}</div>`:''}<div class="row-description">${escapeHTML(p.description)}</div><div class="row-description">${p.sourceRow?`BP แถว ${p.sourceRow}`:``}${p.forecastSourceRow?` · FC แถว ${p.forecastSourceRow}`:``}${p.matchWarning?` · ${escapeHTML(p.matchWarning)}`:``}</div></td><td>${valid(p.priceUSD)?nf.format(p.priceUSD):'—'}</td><td>${valid(p.rmUSD)?nf.format(p.rmUSD):'—'}</td><td>${valid(p.bpTHB)?nf.format(p.bpTHB):'—'}</td><td>${valid(p.fcPriceUSD)?nf.format(p.fcPriceUSD):'—'}</td><td>${valid(p.fcRmUSD)?nf.format(p.fcRmUSD):'—'}</td><td>${valid(p.fcTHB)?nf.format(p.fcTHB):'—'}</td><td>${pct(valid(p.rmRate)?p.rmRate*100:null)}</td></tr>`).join('')}</tbody></table></div><div class="table-note">BP ใช้ Process Price ส่วน FC ใช้ Price ตามหัวตาราง จับคู่รุ่นสินค้าจากรหัสโดยตัดท้าย -S ของ BP ไม่จับคู่ตามลำดับแถว<br>ค่าว่างแสดง “—” แผนจำลองปรับยอดรวม Forecast และยังไม่คำนวณส่วนผสมยอดขายรายรุ่น</div></section>`;}
function sourceRows(q){const role={'BP บริษัท A':'P&L ภาพรวมของบริษัท','BP บริษัท A (PD)':'P&L ของแผนก PD','BP Detail (PD)':'ปริมาณขายและต้นทุนรายสินค้า','Sale Price':'ราคาขาย / วัตถุดิบ / FX','Manpower':'กำลังคน ค่าแรง และ OT','SAP':'ข้อมูลรายการขายต้นทาง','support%RM':'สัดส่วนวัตถุดิบ','ค่าเช่า บริษัท B':'รายได้ค่าเช่า','InvesmentGL':'การลงทุน / ค่าเสื่อมราคา','MC ไม่ได้ใช้งาน':'เครื่องจักรไม่ได้ใช้งาน','Plan Actual + Recover R15':'แผนและผลการผลิต','business_plans':'ประวัติ Business Plan','Job-order Tracking · ยอดผลิต':'ปริมาณผลิตรายวัน'};const external=D.jobOrder?[{name:'Job-order Tracking · ยอดผลิต',dimension:D.jobOrder.status==='loaded'?`${num(D.jobOrder.records.length)} รายการที่อ่านได้`:'ยังเชื่อมต่อไม่ได้',hidden:false,errors:null,checkedRange:D.jobOrder.status==='loaded'?`${displayDate(D.jobOrder.firstDate)}–${displayDate(D.jobOrder.lastDate)}`:(D.jobOrder.error||'ตรวจ CSV ที่ตั้งค่าไว้'),external:true}]:[];const matches=[...D.sources,...external].filter(s=>s.name.toLowerCase().includes(q.toLowerCase()));return matches.length?matches.map(s=>{const status=s.external?(D.jobOrder.status==='loaded'?'<span class="status">เชื่อมต่อแล้ว</span>':'<span class="status warning">อ่านไม่ได้</span>'):s.errors===null?'<span class="muted">ยังไม่ได้ตรวจสูตร</span>':s.errors?'<span class="status warning">'+num(s.errors)+' เซลล์</span>':'<span class="status">ไม่พบในช่วงตรวจ</span>';return `<tr><td>${escapeHTML(s.name)}${s.hidden?'<span class="hidden-source">hidden</span>':''}</td><td>${role[s.name]||'ข้อมูลประกอบ'}</td><td>${escapeHTML(s.dimension)}${s.checkedRange?`<div class="row-description">${s.external?'ช่วงข้อมูล ':'ตรวจ '}${escapeHTML(s.checkedRange)}</div>`:''}</td><td>${status}</td></tr>`;}).join(''):'<tr><td colspan="4" class="empty-state">ไม่พบชื่อแหล่งข้อมูลที่ค้นหา</td></tr>';}
const pageMeta={overview:['ภาพรวม','DEPARTMENT PERFORMANCE','ภาพรวมผลประกอบการ','เห็นผลของแผนก พร้อมตัวเลขที่ใช้ตัดสินใจในแต่ละเดือน'],pnl:['Profit & Loss','DEPARTMENT PROFIT & LOSS','Profit & Loss รายแผนก','เปรียบเทียบแผนกับผลลัพธ์ และติดตามต้นทุนในแต่ละรายการ'],plan:['Business Plan','PLAN YOUR NEXT MOVE','Business Plan','ทดลองปรับสมมติฐาน เพื่อวางเป้าหมายรายได้ ต้นทุน และกำไร'],sources:['ข้อมูลต้นทาง','WORKBOOK CONNECTION','ข้อมูลต้นทาง','ตรวจโครงสร้างเอกสาร และติดตามข้อมูลที่ใช้ใน P&L']};
function render(){const dailyView=state.period==='daily'&&['overview','pnl'].includes(state.page);$('#filters').classList.toggle('daily-range-active',dailyView);const m=dailyView?['ข้อมูลรายวัน','DAILY OPERATIONS','ข้อมูลรายวันจาก Job-order Tracking','เลือกช่วงวันที่เพื่อดูปริมาณผลิตรายชั่วโมงและสรุปตามรุ่นสินค้า']:pageMeta[state.page];$('#breadcrumb').textContent=m[0];$('#eyebrow').textContent=m[1];$('#page-title').textContent=m[2];$('#page-description').textContent=m[3];$$('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===state.page));$('#scope').value=state.scope;$('#period').disabled=['plan','sources'].includes(state.page);$('#scope').disabled=state.page==='sources';$('#period').value=['plan','sources'].includes(state.page)?'year':state.period;$('#daily-shortcut').hidden=!['overview','pnl'].includes(state.page);$('#daily-shortcut').innerHTML=icon(dailyView?'arrow':'calendar')+(dailyView?'กลับไปมุมมองรายเดือน':'ดูยอดผลิตรายวัน');$('#daily-date-filter').hidden=!dailyView;$('#year-filter').hidden=dailyView;const dates=(D.jobOrder?.records||[]).map(record=>record.date).sort(),firstDate=dates[0]||'',lastDate=dates.at(-1)||'';if(!state.dailyStart)state.dailyStart=firstDate;if(!state.dailyEnd)state.dailyEnd=lastDate;for(const [id,value] of [['#daily-date-from',state.dailyStart],['#daily-date-to',state.dailyEnd]]){const input=$(id);input.disabled=!dates.length;input.min=firstDate;input.max=lastDate;input.value=value||'';}$('#unit-label').textContent=dailyView?'หน่วย: ชิ้น / บาท':'หน่วย: ล้านบาท';const label=state.page==='plan'?'Scenario':dailyView?'Job-order':kind();$('#period-kind').textContent=label;$('#period-kind').className='status '+(dailyView?'daily':label==='Actual'&&state.page!=='plan'?'':'forecast');$('#plan-link').style.display=state.page==='plan'||dailyView?'none':'';$('#export').innerHTML=icon('download')+(state.page==='plan'?'ส่งออกแผน CSV':dailyView?'ส่งออกข้อมูลรายวัน CSV':'ส่งออก CSV');$('#view').innerHTML=({overview,pnl,plan,sources}[state.page])();icons();}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3500);}
function openDialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog').showModal();icons($('#dialog'));}
function reference(key){const row=D.rows.find(r=>r.key===key),indexes=selectedIndexes();openDialog(row.label,`<p>แหล่งข้อมูล: <strong>${escapeHTML(scope().sheet)}</strong><br>ช่วงเวลา ${periodLabel()} · แสดงค่าที่อ่านจาก Google Sheets</p><div class="reference-grid">${indexes.map(i=>{const p=scope().periods[i];return `<div><strong>${monthFull[i]}</strong><span>BP <code>${p.bpCol}${scope().rowByKey?.[row.key]||row.row}</code> ${money(p.bp[key])} ลบ.<br>${p.kind} <code>${p.resultCol}${scope().rowByKey?.[row.key]||row.row}</code> ${money(p.result[key])} ลบ.</span></div>`;}).join('')}</div><p style="margin-top:16px">ผลรวมหลายเดือนใช้ผลรวมจากเซลล์รายเดือน อัตราส่วนคำนวณจากยอดรวมของช่วงเวลา</p>`);}
function persist(){const savedScope=state.scope,savedAt=new Date().toISOString(),record={assumptions:{...state.assumptions},initiatives:[...state.initiatives],savedAt};try{localStorage.setItem(storageKey(savedScope),JSON.stringify({...record,draft:true}));storageOK=true;}catch(e){storageOK=false;}state.syncStatus='saving';state.savedAt=savedAt;state.dirty=false;window.PL_DB.savePlan(savedScope,record).then(()=>{try{localStorage.setItem(storageKey(savedScope),JSON.stringify(record));}catch(e){storageOK=false;}if(state.scope===savedScope&&state.savedAt===savedAt){state.syncStatus='saved';state.dirty=false;const label=$('#save-state');if(label)label.textContent=saveLabel();}toast('บันทึก Business Plan ใน Google Sheets แล้ว');}).catch(error=>{if(state.scope===savedScope&&state.savedAt===savedAt){state.syncStatus='error';state.dirty=true;const label=$('#save-state');if(label)label.textContent=saveLabel();}toast('บันทึก Google Sheets ไม่สำเร็จ: '+(error.message||'ตรวจสิทธิ์ชีต'));});return true;}
function initiativeForm(index){const a=index===undefined?{}:state.initiatives[index];openDialog(index===undefined?'เพิ่มแผนงานของแผนก':'แก้ไขแผนงาน',`<form id="initiative-form" data-index="${index??''}"><div class="form-field"><label for="initiative-title">ชื่อแผนงาน</label><input id="initiative-title" name="title" required maxlength="140" value="${escapeHTML(a.title)}" placeholder="เช่น ลดการสูญเสียวัตถุดิบ"></div><div class="form-field"><label for="initiative-owner">ผู้รับผิดชอบ</label><input id="initiative-owner" name="owner" required maxlength="80" value="${escapeHTML(a.owner)}" placeholder="ชื่อผู้รับผิดชอบ / ทีม"></div><div class="form-field"><label for="initiative-goal">เป้าหมายที่วัดได้</label><input id="initiative-goal" name="goal" maxlength="140" value="${escapeHTML(a.goal)}" placeholder="เช่น ลด Scrap จาก 3% เป็น 2%"></div><div class="form-field"><label for="initiative-due">กำหนดเสร็จ</label><input id="initiative-due" type="date" name="due" value="${escapeHTML(a.due)}"></div><div class="form-field"><label for="initiative-status">สถานะ</label><select id="initiative-status" name="status">${['ยังไม่เริ่ม','กำลังดำเนินการ','เสร็จแล้ว'].map(v=>`<option ${a.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="dialog-actions"><button class="button secondary" type="button" data-action="close-dialog">ยกเลิก</button><button class="button primary" type="submit">บันทึกแผนงาน</button></div></form>`);}
function exportCSV(){let rows,name;if(state.page==='plan'){const ms=model();rows=[['Business Plan',scope().label,D.year,'THB','Scenario based on Google Sheets Forecast; Actual months unchanged'],['Assumptions (%)',...Object.keys(state.assumptions)],['Values',...Object.values(state.assumptions)],[],['Month','Revenue scenario THB','Net baseline THB','Net scenario THB','Net delta THB','Kind'],...ms.map((p,i)=>[p.month,p.revenue,scope().periods[i].result.net,p.net,diff(p.net,scope().periods[i].result.net),p.kind]),[],['Initiative','Owner','Goal','Due','Status'],...state.initiatives.map(a=>[a.title,a.owner,a.goal,a.due,a.status])];name='Business-Plan-'+D.year+'-'+state.scope;}else if(state.period==='daily'&&['overview','pnl'].includes(state.page)){const summary=dailySummary();rows=[['Source','Job-order Tracking'],['Date from',state.dailyStart],['Date to',state.dailyEnd],['Production quantity (FG Qty)',summary.qty],['Estimated production value THB',summary.estimatedValue],[],['Date','Time','Job order','Model','FG Qty','Price FC THB / unit','Price base model','Match score / method','Price source','Estimated value THB','Line','Shift'],...summary.records.map(record=>{const match=priceMatchForModel(record.model),price=match&&!match.ambiguous?match.price:null,matchLabel=!match?'No match':match.ambiguous?`Ambiguous ${match.score.toFixed(1)}%`:match.exact?'Exact 100%':`Prefix ${match.score.toFixed(1)}%`;return [record.date,record.time,record.jobNo,record.model,record.qty,price,match?.ambiguous?match.candidates.map(item=>item.sourceModel).join(' | '):match?.sourceModel||'',matchLabel,match?.priceSource||'',valid(price)?price*record.qty:null,record.line,record.shift];})];name='Job-order-'+state.dailyStart+'_to_'+state.dailyEnd;}else if(state.page==='sources'){rows=[['Source workbook',D.source],['Sheet','Range','Error count in inspected ranges','Hidden'],...D.sources.map(s=>[s.name,s.dimension,s.errors,s.hidden])];name='Data-Sources';}else{const a=aggregate('result'),b=aggregate('bp');rows=[['Department',scope().label,'Period',periodLabel(),'Currency','THB'],['Source',D.source,'Sheet',scope().sheet,'Type',kind()],[],['Item','BP THB',kind()+' THB','Result minus BP THB','Variance %','Result / revenue %'],...D.rows.map(r=>[r.label,b[r.key],a[r.key],diff(a[r.key],b[r.key]),ratio(diff(a[r.key],b[r.key]),Math.abs(b[r.key])),ratio(a[r.key],a.revenue)])];name='PL-'+D.year+'-'+state.scope+'-'+state.period;}const cell=v=>{if(v===null||v===undefined)return '';let s=String(v);if(typeof v==='string'&&/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('ส่งออกข้อมูล CSV แล้ว');}
$('#period').innerHTML=monthFull.map((m,i)=>`<option value="${i}">${m} ${D.year}</option>`).join('')+[1,2,3,4].map(i=>`<option value="q${i}">ไตรมาส ${i} / ${D.year}</option>`).join('')+`<option value="year">ทั้งปี ${D.year}</option><option value="daily">รายวัน · Job-order Tracking</option>`;
$('#scope').addEventListener('change',e=>{state.scope=e.target.value;const saved=getSavedPlan(state.scope);state.assumptions={...defaults,...(saved.assumptions||{})};state.initiatives=Array.isArray(saved.initiatives)?saved.initiatives:[];state.savedAt=saved.savedAt||null;state.syncStatus=saved.savedAt?(saved.draft?'error':'saved'):'idle';state.dirty=!!saved.draft;render();});
$('#period').addEventListener('change',e=>{if(e.target.value==='daily'&&state.period!=='daily')state.previousPeriod=state.period;state.period=e.target.value;render();});
$('#daily-shortcut').addEventListener('click',()=>{if(state.period==='daily')state.period=state.previousPeriod||'0';else{state.previousPeriod=state.period;state.period='daily';}render();});
$('#daily-date-from').addEventListener('change',e=>{state.dailyStart=e.target.value||state.dailyEnd;if(state.dailyStart>state.dailyEnd)state.dailyEnd=state.dailyStart;render();});
$('#daily-date-to').addEventListener('change',e=>{state.dailyEnd=e.target.value||state.dailyStart;if(state.dailyEnd<state.dailyStart)state.dailyStart=state.dailyEnd;render();});
$('#export').addEventListener('click',exportCSV);
$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#dialog-close').addEventListener('click',()=>$('#dialog').close());
$('#help').addEventListener('click',()=>openDialog('เกี่ยวกับ P&L Workspace','<p>เว็บอ่าน P&L จากแท็บข้อมูลใน Google Sheets และบันทึก Business Plan เป็นประวัติแต่ละรุ่นในแท็บ business_plans</p><p>ผู้ใช้ต้องเข้าสู่ระบบ Google และมีสิทธิ์แก้ไขชีตนี้ ปี P&L ใช้ปีจากหัวตาราง สูตรผิดพลาดและค่าว่างแสดงเป็น “—”</p><p>ต้นแบบยังไม่มี workflow ส่งอนุมัติแผนหรือแยกสิทธิ์ผู้กรอกและผู้อนุมัติ</p>'));
document.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-detail],[data-month],[data-reference],[data-edit-initiative],[data-delete-initiative]');if(!target)return;const d=target.dataset;if(d.detail!==undefined){state.detail=d.detail==='true';render();}if(d.month!==undefined){state.period=d.month;render();}if(d.reference)reference(d.reference);if(d.editInitiative!==undefined)initiativeForm(Number(d.editInitiative));if(d.deleteInitiative!==undefined){const i=Number(d.deleteInitiative),title=state.initiatives[i].title;openDialog('ลบแผนงาน',`<p>ลบแผนงาน “${escapeHTML(title)}” จาก Google Sheets</p><div class="dialog-actions"><button class="button secondary" data-action="close-dialog">ยกเลิก</button><button class="button primary" data-action="confirm-delete" data-index="${i}">ลบแผนงาน</button></div>`);}switch(d.action){case 'sources':location.hash='sources';break;case 'save-plan':if(persist())$('#save-state').textContent=saveLabel();break;case 'reset-plan':state.assumptions={...defaults};state.dirty=true;render();toast('คืนสมมติฐานเป็น Forecast ต้นทางแล้ว');break;case 'add-initiative':initiativeForm();break;case 'close-dialog':$('#dialog').close();break;case 'confirm-delete':state.initiatives.splice(Number(d.index),1);persist();$('#dialog').close();render();toast('ลบแผนงานแล้ว');break;}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='source-search'){$('#source-rows').innerHTML=sourceRows(el.value);return;}const key=el.dataset.driver||el.dataset.slider;if(!key)return;let v=Number(el.value);if(el.value.trim()===''||!Number.isFinite(v)||v<Number(el.min)||v>Number(el.max)){el.setCustomValidity('ระบุตัวเลขระหว่าง '+el.min+' ถึง '+el.max);el.reportValidity();return;}el.setCustomValidity('');state.assumptions[key]=v;state.dirty=true;const paired=$(el.dataset.driver?`[data-slider="${key}"]`:`[data-driver="${key}"]`);paired.value=v;$('#plan-results').innerHTML=planResults();icons($('#plan-results'));$('#save-state').textContent=saveLabel();});
document.addEventListener('change',e=>{const key=e.target.dataset.driver;if(key&&e.target.validationMessage){e.target.value=state.assumptions[key];e.target.setCustomValidity('');}});
document.addEventListener('submit',e=>{if(e.target.id!=='initiative-form')return;e.preventDefault();const form=e.target,f=new FormData(form),a=Object.fromEntries(f.entries());a.title=a.title.trim();a.owner=a.owner.trim();if(!a.title||!a.owner){toast('กรอกชื่อแผนงานและผู้รับผิดชอบ');return;}const i=form.dataset.index;if(i==='')state.initiatives.push(a);else state.initiatives[Number(i)]=a;persist();$('#dialog').close();render();});
function route(){const p=location.hash.slice(1)||'overview';state.page=pageMeta[p]?p:'overview';$('#sidebar').classList.remove('open');render();}
window.addEventListener('hashchange',route);route();

$('#scope').innerHTML=D.scopes.map(s=>`<option value="${escapeHTML(s.id)}">${escapeHTML(s.label)}</option>`).join('');
$('#scope').value=state.scope;
$('#year').innerHTML=`<option>${D.year}</option>`;
$('.page-footer').innerHTML=`<span><i></i>ข้อมูลจาก Google Sheets · ปี ${D.year}</span><span>อ่านล่าสุด ${new Date(D.loadedAt||Date.now()).toLocaleString('th-TH')}</span>`;
